const { parseCSV, transform, validate } = require('./src/pipeline');
const rows = parseCSV('a,b\nc,d');
if (JSON.stringify(rows) !== JSON.stringify([['a','b'],['c','d']])) { console.error('FAIL parse', rows); process.exit(1); }
const t = transform(rows);
if (JSON.stringify(t) !== JSON.stringify([['A','B'],['C','D']])) { console.error('FAIL transform', t); process.exit(1); }
if (!validate(rows)) { console.error('FAIL validate'); process.exit(1); }
if (validate([['a','b'],['c']])) { console.error('FAIL validate bad'); process.exit(1); }
console.log('PASS');
